(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.045-t*0.5)*6+Math.cos(y*0.03+t*0.4)*5;
  const w2y = Math.cos(y*0.04+t*0.45)*6+Math.sin(x*0.035-t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75)*50,0.11,2.1],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.85+1)*40,0.05,2.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*1.3-t*sp*0.8+2.1);
    iS2+=Math.cos(d*f*0.5+t*sp*0.4+0.7);
  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*5-t*2.0)+Math.cos(dist*0.06-ang*2+t*1.8))*0.25;
  const micro=(Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)+Math.sin((sx-sy)*0.2+t*4)*0.3)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+spiral2+micro)*1.8);
  const cross=r1*r2*1.5;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const breathe=0.9+Math.sin(t*0.4)*0.1;
  const blend=(r1*0.5+r2*0.25+cross*0.15+cell*0.1)*breathe;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,35,85],[15,70,120],[20,110,135],
    [35,150,140],[80,175,120],[160,190,90],
    [210,185,65],[220,155,55],[215,110,60],
    [195,70,65],[160,40,70],[110,25,65],
    [60,18,55],[25,12,48],[5,10,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(Math.abs(blend)*Math.PI)*0.25;
  const edge=Math.abs(blend)>0.65?1.2:Math.abs(blend)>0.4?1.05:0.95;
  const glow=Math.max(0,Math.abs(blend)-0.5)*0.6;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
